/bin/bash -lc "cat > src/util/checkoutRequest.mjs <<'EOF'
/**
 * Builds the checkout request the storefront POSTs to cart/<cartCode>/checkout.
 * Body field names follow the backend order request classes
 * (PersistableAnonymousOrder / PersistableOrder / PersistablePayment).
 */
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  return {
    method: 'post',
    path: "'`cart/${cartCode}/checkout`,
    body: {
      quoteId: shippingOptionId,
      currency,
      termsAccepted: agreedToTerms,
      orderNote: comments,
      payment: {
        paymentType: '"'CREDITCARD',
        transactionType: 'CAPTURE',
        processor: paymentModule,
        cardToken: paymentToken,
        amount,
      },
    },
  };
}
EOF
node --input-type=module -e \"
import { buildCheckoutRequest } from './src/util/checkoutRequest.mjs';
console.log(JSON.stringify(buildCheckoutRequest({ cartCode:'C123', shippingOptionId:42, currency:'USD', paymentToken:'tok_abc', paymentModule:'stripe', amount:100, agreedToTerms:true, comments:'gift' }), null, 2));
\""
